script:
frappe.ui.form.on("User", {
	refresh(frm) {
		frm.set_query("ns_department", () => ({
			filters: { organization: frm.doc.ns_organization || "" },
		}));
	},
	ns_organization(frm) {
		frm.set_value("ns_department", "");
		frm.set_query("ns_department", () => ({
			filters: { organization: frm.doc.ns_organization || "" },
		}));
	},
});
